{
  "name": "opencode-output-styles",
  "version": "0.2.2",
  "description": "Opt-in output styles for OpenCode — learning mode plus your own markdown styles, injected into the system prompt.",
  "license": "MIT",
  "author": "Felipe Alves",
  "type": "module",
  "main": "./src/index.ts",
  "exports": {
    ".": "./src/index.ts"
  },
  "files": [
    "src",
    "!src/**/*.test.ts"
  ],
  "keywords": [
    "opencode",
    "opencode-plugin",
    "output-style",
    "learning"
  ],
  "engines": {
    "opencode": ">=1.18.0"
  },
  "repository": {
    "type": "git",
    "url": "git+https://github.com/felipeverse/opencode-output-styles.git"
  },
  "homepage": "https://github.com/felipeverse/opencode-output-styles#readme",
  "bugs": {
    "url": "https://github.com/felipeverse/opencode-output-styles/issues"
  },
  "scripts": {
    "typecheck": "tsc --noEmit",
    "test": "vitest run",
    "lint": "biome check .",
    "format": "biome check --write ."
  },
  "peerDependencies": {
    "@opencode-ai/plugin": ">=1.18.0"
  },
  "devDependencies": {
    "@biomejs/biome": "^2.6.4",
    "@opencode-ai/plugin": "^1.19.5",
    "@types/node": "^26.6.6",
    "typescript": "^7.0.2",
    "vitest": "^5.0.5"
  }
}
